from lib import *
S = SS('m77')
steps = [
    step("mongod --auth 启动后,没有认证的连接 find → code 13 Unauthorized(not authorized on test to execute command { find: \"t\" ... }),listCollections 同样被拒;ping 不需要认证,hello 还会告诉你可用机制 ['SCRAM-SHA-1', 'SCRAM-SHA-256']。localhost 例外:还没有任何用户时,本机连接不认证就能 createUser root;之后再不认证创建第二个用户 → code 13 Command createUser requires authentication。", t=tl(S(1)), mark=lidx(S(1), 'find 被拒', 'listCollections 被拒', 'localhost 例外', '创建第一个用户之后'), done=lidx(S(1), '不需要认证的命令'), kv=KV([['未认证 find', 'code 13 Unauthorized'], ['ping / hello', '不需要认证'], ['localhost 例外', '第一个用户可以不认证创建'], ['第二个用户', 'code 13,需要认证']], ['localhost 例外'])),
    step("admin.system.users 里 alice 的文档顶层字段是 _id、credentials、db、roles、user、userId(_id = admin.alice),没有明文密码(\"alicepw\" 不在文档里)。credentials 里有两种机制:SCRAM-SHA-1(iterationCount 10000,salt 16 字节,storedKey / serverKey 各 20 字节)和 SCRAM-SHA-256(iterationCount 15000,salt 28 字节,storedKey / serverKey 各 32 字节)。", t=tl(S(2)), mark=lidx(S(2), 'SCRAM-SHA-1: iterationCount', 'SCRAM-SHA-256: iterationCount', '明文'), done=lidx(S(2), '顶层字段'), kv=KV([['SCRAM-SHA-1', 'i = 10000,salt 16 B,键 20 B'], ['SCRAM-SHA-256', 'i = 15000,salt 28 B,键 32 B'], ['明文密码', '不存']], ['SCRAM-SHA-256'])),
    step("手写 SCRAM-SHA-256:第 1 条 saslStart,payload 是 n,,n=alice,r=<客户端 nonce>;服务器回 conversationId = 1、done = False、payload 里是 r=<客户端 nonce+服务端 nonce,56 字符>、s=<salt>、i=15000。第 2 条 saslContinue,payload 是 c=biws,r=…,p=<32 字节 ClientProof 的 base64>;服务器回 done = True 和 v=<ServerSignature>。自己用 PBKDF2 算出的 storedKey、serverKey 和 system.users 里的相等(True / True),服务器签名校验通过,握手共 2 条命令;不带 skipEmptyExchange 要 3 条(多一次空 payload 的 saslContinue)。", t=tl(S(3)), mark=lidx(S(3), '1. 客户端', '2. 客户端', '自己算出的 storedKey', '不带 skipEmptyExchange'), done=lidx(S(3), '服务器 → 客户端:conversationId', '服务器 → 客户端:done = True'), kv=KV([['握手命令数', '2(saslStart + saslContinue)'], ['不带 skipEmptyExchange', '3'], ['storedKey / serverKey', '与 system.users 相等'], ['密码是否传输', '没有,只传 ClientProof']], ['握手命令数'])),
    step("失败的认证:alice 密码错 → code 18 AuthenticationFailed: Authentication failed.;不存在的用户 nobody → 完全相同的 code 18 和同一句话(从错误里分不出用户存不存在);alice 在错误的 authSource(test)→ 同样 code 18;机制 PLAIN → code 334 MechanismUnavailable: ... mechanism PLAIN which is not enabled。", t=tl(S(4)), mark=lidx(S(4), '密码错的 alice', '不存在的用户', '错误的 authSource', 'PLAIN'), done=lidx(S(4), '正确的 alice'), kv=KV([['密码错', 'code 18 Authentication failed.'], ['用户不存在', 'code 18 同一句话'], ['错误 authSource', 'code 18'], ['PLAIN', 'code 334 MechanismUnavailable']], ['用户不存在'])),
    step("alice 只有 test 的 read:读 test.t 返回 [],写 test.t → code 13 not authorized on test to execute command { insert ... };读没有授权的 test2 库 → code 13 on test2。root 给 alice 加 readWrite@test 后,alice 同一个已认证连接不用重新登录就写成功了(inserted_id = 1);root 回收之后,同一连接再写又是 code 13。", t=tl(S(5)), mark=lidx(S(5), 'alice 写 test.t', 'alice 读 test2.t', '同一个连接写', '同一连接再写'), done=lidx(S(5), 'alice 读 test.t'), kv=KV([['read@test 写入', 'code 13'], ['未授权的库', 'code 13'], ['grant readWrite', '同一连接立即能写'], ['revoke', '同一连接立即又被拒']], ['grant readWrite'])),
    step("认证的代价(新建 MongoClient + ping,15 次中位数,本机无网络延迟):不认证 1.1 ms,SCRAM-SHA-1 2.5 ms,SCRAM-SHA-256 3.4 ms——SCRAM-SHA-256(i = 15000)比 SCRAM-SHA-1(i = 10000)多约 0.9 ms。", t=tl(S(6)), mark=lidx(S(6), '不认证的 ping'), done=lidx(S(6), '不认证的 ping'), b=bars([['不认证', 1.1, '1.1 ms'], ['SCRAM-SHA-1', 2.5, '2.5 ms'], ['SCRAM-SHA-256', 3.4, '3.4 ms']], 3.4, mark=[2], done=[0, 1]), kv=KV([['不认证', '1.1 ms'], ['SCRAM-SHA-1', '2.5 ms'], ['SCRAM-SHA-256', '3.4 ms']], ['SCRAM-SHA-256'])),
]
A = mkartm('m77', 77, 'MongoDB,SCRAM,认证,授权,roles,saslStart,真实验证,动画演示',
    '实测 SCRAM 认证:--auth 下未认证 code 13、localhost 例外;system.users 里只存 salt/iterationCount/storedKey/serverKey(SHA-256 是 15000 次迭代);手写 saslStart/saslContinue 握手(2 条命令)并验证 storedKey;密码错与用户不存在返回同一个 code 18;角色授予回收立即对同一连接生效;SCRAM-SHA-256 认证约 3.4 ms。',
    'MongoDB 的 SCRAM 认证握手到底几步、传了什么?服务端存了什么?授权不对时报什么错?这篇手写一遍握手来验证。',
    [('2 条', 'skipEmptyExchange 下 SCRAM-SHA-256 握手需要的命令数(否则 3 条)'), ('18', '密码错和用户不存在都是同一个错误码 AuthenticationFailed'), ('15000', 'SCRAM-SHA-256 的 iterationCount(SHA-1 是 10000)')],
    [('未认证与 localhost 例外', '<p><code>--auth</code> 下未认证的 find 是 code 13;还没有用户时本机连接可以创建第一个用户,此后创建用户也要认证。</p>'),
     ('system.users', '<p>用户文档里只有每种机制的 salt、iterationCount、storedKey、serverKey,没有明文密码。</p>'),
     ('手写握手', '<p><code>saslStart</code> 发 <code>n,,n=user,r=nonce</code>,服务器回 salt 和 iterationCount;<code>saslContinue</code> 发 ClientProof,服务器回 ServerSignature。我们自己算出的 storedKey 与服务端一致。</p>'),
     ('失败的认证', '<p>密码错、用户不存在、authSource 不对都是同样的 <code>code 18 Authentication failed.</code>。</p>'),
     ('授权', '<p>只有 read 的用户写入是 code 13;grant/revoke 对同一个已认证连接立即生效。</p>'),
     ('代价', '<p>新建连接并认证:不认证 1.1 ms,SCRAM-SHA-1 2.5 ms,SCRAM-SHA-256 3.4 ms。</p>')],
    steps,
    [ENV_M + '。单机 mongod --auth(无 keyfile / TLS),pymongo 与手写 saslStart/saslContinue',
     '没有验证:x.509、LDAP、Kerberos 等其它机制;副本集内部认证(keyFile / clusterAuthMode);TLS 对认证的影响;密码长度与 SASLprep 对非 ASCII 密码的处理;authenticationMechanisms 参数的限制;用户缓存(userCacheInvalidationIntervalSecs)在分片集群上的传播延迟;角色变更在分片集群或其它节点上的生效时间(这里只测了单机)'],
    'SCRAM 认证握手')
